using System.Net;
using System.Text;
using SalekhPos.Desktop.Infrastructure.Management;
using Xunit;
namespace SalekhPos.Desktop.Tests; public sealed class BillingManagerHttpTests { [Fact] public async Task RejectsWrongInvoiceIdentity() { var o = Guid.NewGuid(); var id = Guid.NewGuid(); using var c = Client(_ => Json($$"""{"invoiceId":"{{Guid.NewGuid():D}}","accountId":"{{Guid.NewGuid():D}}","number":"INV","currency":"GEL","status":"open","netAmount":1,"taxAmount":0,"grossAmount":1,"paidAmount":0,"balance":1,"issuedAt":"2026-09-18T08:00:00Z","dueAt":"2026-10-18T08:00:00Z"}""")); await Assert.ThrowsAsync<InvalidOperationException>(() => new HttpBillingManager(c).GetInvoiceAsync(o, id, default)); } private static HttpClient Client(Func<HttpRequestMessage, HttpResponseMessage> f) => new(new H(f)) { BaseAddress = new("https://pos.test/") }; private static HttpResponseMessage Json(string x) => new(HttpStatusCode.OK) { Content = new StringContent(x, Encoding.UTF8, "application/json") }; private sealed class H(Func<HttpRequestMessage, HttpResponseMessage> f) : HttpMessageHandler { protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r, CancellationToken ct) => Task.FromResult(f(r)); } }
